// CreateTable creates the Item table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *Item) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the Item table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *Item) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ItemTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetItemPostgresTableSchema()
	} else {
		schema = GetItemTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Item table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *Item) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ItemTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Item$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (search_description)`,
		fmt.Sprintf("%s$Item$search_description", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index search_description: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (inventory_posting_group)`,
		fmt.Sprintf("%s$Item$inventory_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index inventory_posting_group: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (shelf_bin_no)`,
		fmt.Sprintf("%s$Item$shelf_bin_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index shelf_bin_no: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (vendor_no)`,
		fmt.Sprintf("%s$Item$vendor_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor_no: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gen_prod_posting_group)`,
		fmt.Sprintf("%s$Item$gen_prod_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gen_prod_posting_group: %w", err)
	}
	var keys []sift.Key
	for _, spec := range itemSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ItemTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ItemTableName, keys)
}

// itemSIFTSpecs are the table's keys with sum_index_fields
func itemSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *Item) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, ItemTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range itemSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ItemTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ItemTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ItemTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

