// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Item) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Item) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"BOM_Component", false, "parent_item_no", "", 0}, {"BOM_Component", false, "no", "type", 1}, {"BOM_Journal_Line", false, "item_no", "", 0}, {"Item", false, "sales_qty_disc_code", "", 0}, {"Item", false, "alternative_item_no", "", 0}, {"Item_Application_Entry", false, "item_no", "", 0}, {"Item_Journal_Line", false, "item_no", "", 0}, {"Item_Journal_Line", false, "source_no", "source_type", 3}, {"Item_Ledger_Entry", false, "item_no", "", 0}, {"Item_Ledger_Entry", false, "source_no", "source_type", 3}, {"Item_Price", false, "item_no", "", 0}, {"Item_Translation", false, "item_no", "", 0}, {"Item_Unit_of_Measure", false, "item_no", "", 0}, {"Item_Variant", false, "item_no", "", 0}, {"Item_Vendor", false, "item_no", "", 0}, {"Phys_Inventory_Ledger_Entry", false, "item_no", "", 0}, {"Purchase_Line", false, "no", "type", 2}, {"Sales_Cr_Memo_Line", false, "no", "type", 2}, {"Sales_Invoice_Line", false, "no", "type", 2}, {"Sales_Line", false, "no", "type", 2}, {"Sales_Shipment_Line", false, "no", "type", 2}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// Delete removes the record from the database
func (t *Item) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.No,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete Item: %v\n", err)
		return false
	}
	return true
}

// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *Item) CalcFields(fieldNames ...string) {
	// If no field names specified, calculate all FlowFields
	if len(fieldNames) == 0 {
		t.calcFlowField_bill_of_materials()
		t.calcFlowField_comment()
		t.calcFlowField_quantity_on_hand()
		t.calcFlowField_net_invoiced_qty()
		t.calcFlowField_net_change()
		t.calcFlowField_purchases_qty()
		t.calcFlowField_sales_qty()
		t.calcFlowField_positive_adjmt_qty()
		t.calcFlowField_negative_adjmt_qty()
		t.calcFlowField_purchases_lcy()
		t.calcFlowField_sales_lcy()
		t.calcFlowField_positive_adjmt_lcy()
		t.calcFlowField_negative_adjmt_lcy()
		t.calcFlowField_cogs_lcy()
		t.calcFlowField_transferred_qty()
		t.calcFlowField_transferred_lcy()
		return
	}

	// Calculate only specified fields
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "bill_of_materials":
			t.calcFlowField_bill_of_materials()
		case "comment":
			t.calcFlowField_comment()
		case "quantity_on_hand":
			t.calcFlowField_quantity_on_hand()
		case "net_invoiced_qty":
			t.calcFlowField_net_invoiced_qty()
		case "net_change":
			t.calcFlowField_net_change()
		case "purchases_qty":
			t.calcFlowField_purchases_qty()
		case "sales_qty":
			t.calcFlowField_sales_qty()
		case "positive_adjmt_qty":
			t.calcFlowField_positive_adjmt_qty()
		case "negative_adjmt_qty":
			t.calcFlowField_negative_adjmt_qty()
		case "purchases_lcy":
			t.calcFlowField_purchases_lcy()
		case "sales_lcy":
			t.calcFlowField_sales_lcy()
		case "positive_adjmt_lcy":
			t.calcFlowField_positive_adjmt_lcy()
		case "negative_adjmt_lcy":
			t.calcFlowField_negative_adjmt_lcy()
		case "cogs_lcy":
			t.calcFlowField_cogs_lcy()
		case "transferred_qty":
			t.calcFlowField_transferred_qty()
		case "transferred_lcy":
			t.calcFlowField_transferred_lcy()
		}
	}
}

