// Count returns the number of records matching current filters
func (t *Item) Count() int {
	tableName := fmt.Sprintf("%s$%s", t.company, ItemTableName)
	where, args := t.buildWhereClause()

	query := fmt.Sprintf(`SELECT COUNT(*) FROM "%s" WHERE %s`, tableName, where)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	var count int
	err := t.exec().QueryRow(query, args...).Scan(&count)
	if err != nil {
		fmt.Printf("Error: Failed to count Item: %v\n", err)
		return 0
	}

	return count
}

// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *Item) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := fmt.Sprintf("%s$%s", t.company, ItemTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, no_2, description, search_description, description_2, class, base_unit_of_measure, price_unit_conversion, inventory_posting_group, shelf_bin_no, sales_qty_disc_code, item_cust_disc_gr, allow_invoice_disc, statistics_group, commission_group, unit_price, price_profit_calculation, profit_percent, costing_method, unit_cost, standard_cost, last_direct_cost, average_cost, minimum_unit_price, indirect_cost_percent, vendor_no, vendor_item_no, lead_time_calculation, reorder_point, maximum_inventory, reorder_quantity, alternative_item_no, unit_list_price, duty_due_percent, duty_code, gross_weight, net_weight, units_per_parcel, unit_volume, durability, freight_type, duty_unit_conversion, country_purchased_code, budget_quantity, budgeted_amount, budget_profit, blocked, last_date_modified, price_includes_tax, tax_bus_posting_gr_price, gen_prod_posting_group, picture, country_of_origin_code, no_series, tax_group_code, tax_prod_posting_group, reserve, inventory_value_zero, rounding_precision, sales_unit_of_measure, purch_unit_of_measure FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Item: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
