// SetFlowFilter sets a FlowFilter field's filter expression (SETFILTER on a
// FlowFilter field); FlowFields applying it use it from then on. "" clears it.
func (t *Item) SetFlowFilter(field, expr string) error {
	switch field {
	case "date_filter":
		if err := flowfilter.Validate(flowfilter.KindDate, expr); err != nil {
			return err
		}
		t.Date_filter = expr
		return nil
	case "department_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Department_filter = expr
		return nil
	case "project_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Project_filter = expr
		return nil
	case "location_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Location_filter = expr
		return nil
	case "drop_shipment_filter":
		if err := flowfilter.Validate(flowfilter.KindBool, expr); err != nil {
			return err
		}
		t.Drop_shipment_filter = expr
		return nil
	case "variant_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Variant_filter = expr
		return nil
	}
	return fmt.Errorf("%q is not a FlowFilter field of Item", field)
}

// GetFlowFilterFields returns the FlowFilter fields (name and flowfilter kind)
func (t *Item) GetFlowFilterFields() []tables.FlowFilterFieldInfo {
	return []tables.FlowFilterFieldInfo{
		{Name: "date_filter", Kind: string(flowfilter.KindDate)},
		{Name: "department_filter", Kind: string(flowfilter.KindCode)},
		{Name: "project_filter", Kind: string(flowfilter.KindCode)},
		{Name: "location_filter", Kind: string(flowfilter.KindCode)},
		{Name: "drop_shipment_filter", Kind: string(flowfilter.KindBool)},
		{Name: "variant_filter", Kind: string(flowfilter.KindCode)},
	}
}

